실시간 자산 현황 (Dashboard)

d3 = require("d3@7")

data = d3.csv("https://docs.google.com/spreadsheets/d/e/2PACX-1vTQi4SzVyyjp3DnusOmC6Cmyehy-Ro7ZT4ZndYplvu9lVE2G4xEK3OFf1TiV3JXzN4Rz8PikXqAzskw/pub?gid=0&single=true&output=csv")

// 2. 도넛 차트 구현
Plot.plot({
  height: 400,
  width: 600,
  marks: [
    Plot.arc(data, Plot.stackY({
      value: d =&gt; parseFloat(d.Portfolio_Weight.replace('%', '')) || 0,
      fill: "Ticker",
      title: d =&gt; `${d.Ticker}: ${d.Portfolio_Weight}`,
      innerRadius: 100,
      outerRadius: 160,
      stroke: "white",
      strokeWidth: 2
    })),
    Plot.text(["Portfolio"], {frameAnchor: "middle", fontSize: 18, fontWeight: "500"})
  ],
  color: {
    range: ["#007AFF", "#5AC8FA", "#4CD964", "#FFCC00", "#FF9500", "#FF2D55", "#5856D6"]
  },
  style: {
    background: "transparent"
  }
})
